import fs from 'node:fs/promises';
import path from 'node:path';

// These paths are generated by process-media and build.mjs. Scan the actual
// output so links, srcset, captions, social images and deferred media all count.
const mediaReference = /\bmedia\/(?:derived\/[a-z0-9-]+\/[a-z0-9-]+\.[a-z0-9]+|captions\/[a-z0-9-]+\.vtt)\b/g;

export async function keepPublicMedia(outputDir, documents) {
  const references = new Set();
  for (const file of documents) {
    const source = await fs.readFile(path.join(outputDir, file), 'utf8');
    if (/\bmedia\/originals\//i.test(source)) {
      throw new Error(`${file} verwijst naar een origineel uit de beeldbank. Kies een webversie.`);
    }
    for (const reference of source.matchAll(mediaReference)) references.add(reference[0]);
  }

  const mediaDir = path.join(outputDir, 'media');
  let removed = 0;
  async function prune(directory) {
    for (const entry of await fs.readdir(directory, { withFileTypes: true })) {
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) {
        await prune(file);
        if (!(await fs.readdir(file)).length) await fs.rmdir(file);
        continue;
      }
      const relative = path.relative(outputDir, file).split(path.sep).join('/');
      if (references.has(relative)) continue;
      await fs.unlink(file);
      removed++;
    }
  }
  await fs.mkdir(mediaDir, { recursive: true });
  // Fail before publishing when an emitted page references a missing file.
  for (const file of references) await fs.access(path.join(outputDir, file));
  await prune(mediaDir);
  return { retained: references.size, removed };
}
